        self.value = value
        self.left = left
        self.right = right

class BST:
    def __init__(self):
        self.root = None

    def insert(self, value):
        if self.root is None:
            self.root = NAME_1(value)
        else:
            self._insert(value)

    def _insert(self, value):
        if value < self.root.value:
            if self.root.left is None:
                self.root.left = NAME_1(value)
            else:
                self._insert(value)
                self.root.left.right = NAME_1(value)
        else:
            if self.root.right is None:
                self.root.right = NAME_1(value)
            else:
                self._insert(value)
                self.root.right.left = NAME_1(value)

    def search(self, value):
        if self.root is None:
            return False
        if self.root.value == value:
            return True
        elif value < self.root.value:
            return self.search(value)
        else:
            return self.search(value)

    def delete(self, value):
        if self.root is None:
            return False
        if value == self.root.value:
            self.root = self.root.left
            return True
        elif value < self.root.value:
            if self.root.left is None:
                self.root = self.root.right
            else:
                self.delete(value)
                self.root.left.right = self.root.right
        else:
            if self.root.right is None:
                self.root = self.root.left
            else:
