def tetris(board, state):
    if not board:
        return
    if state == Tetris.DONE:
        print(board)
    for i in range(len(board)):
        for j in range(len(board[0])):
            piece = board[i][j]
            if piece == ' ':
                board = tetris(board[:i], state)
                board[i] = Tetris.GAP
            elif piece == Tetris.GAP:
                board = tetris(board[i+1:], state)
                board[i] = ' '
            elif piece == Tetris.O:
                piece = tetris(board, Tetris.O_FALLING)
                if piece == ' ':
                    board = tetris(board[:i], state)
                    board[i] = Tetris.O
            elif piece == Tetris.X:
                piece = tetris(board, Tetris.X_FALLING)
                if piece == ' ':
                    board = tetris(board[:i], state)
                    board[i] = Tetris.X
            elif piece == Tetris.Z:
                piece = tetris(board, Tetris.Z_FALLING)
                if piece == ' ':
                    board = tetris(board[:i], state)
                    board[i] = Tetris.Z
            else:
                piece = tetris(board, state)
                if piece == ' ':
                    board = tetris(board[:i], state)
                    board[i] = piece
