def find_next_palindrome(num_list):
    if not num_list:
        return [0] * len(num_list)

    largest_num = max(num_list)
    smallest_num = min(num_list)

    midpoint = (smallest_num + largest_num) // 2

    if largest_num == 9:
        updated_largest_num = 0
        while updated_largest_num <= midpoint:
            if str(updated_largest_num) == str(midpoint)[::-1]:
                break
            updated_largest_num += 1
        if updated_largest_num > midpoint:
            return [0] * len(num_list)

    if smallest_num == largest_num:
        smallest_num += 1
    else:
        smallest_num = 0

    while str(smallest_num) != str(largest_num)[::-1]:
        smallest_num += 1

    return [smallest_num] + num_list[:-1] + [largest_num]

# Example usage:
