import heapq

def shortest_path_length(line_length, start, destination):
    n = len(line_length)
    if n == 0:
        return float('inf')

    unknown_points = [(start, 0)]
    known_points = set()
    dist = [0] * n
    line_length[start] = 0

    while unknown_points:
        min_val = min(unknown_points, key=lambda x: x[1])
        node, dist_val = min_val
        if node == destination:
            return dist_val

        successors = [(i, dist_val + line_length[node]) for i in range(n) if i != node and i not in known_points]
        heapq.heappush(unknown_points, successors)
        known_points.add(node)
