```python
class Queue:
    def __init__(self):
        self.queue1 = []
        self.queue2 = []
    def enqueue(self, item):
        self.queue1.append(item)
        self.queue2.append(item)
    def dequeue(self):
        if self.queue1:
            item = self.queue1.pop(0)
            self.queue2.append(item)
        else:
            raise IndexError("Queue is empty")
        return item
    def peek(self):
        if self.queue1:
            return self.queue1.pop(0)
        else:
            raise IndexError("Queue is empty")
