import heapq

def fibonacci_heap_insert_or_update(heap, node, distance):
    if node not in heap:
        heapq.heappush(heap, (distance, node))
    else:
        heapq.heappush(heap, (distance, node))
        heapq.heapify(heap)

def shortest_path_length(graph, start_node, destination_node):
    unknown_points = [(0, start_node)]
    visited_points = set()

    while True:
        distance, current_node = heapq.heappop(unknown_points)

        if current_node == destination_node:
            return distance

        if current_node not in visited_points:
            visited_points.add(current_node)

            successors = graph[current_node]
            for successor in successors:
                if successor not in visited_points and successor not in unknown_points:
                    distance_to_destination = float('inf')

                    for neighbor in successors:
                        if neighbor == destination_node:
                            distance_to_destination = 0
                            break

                    fibonacci_heap_insert_or_update(unknown_points, successor, distance_to_destination)

    return float('inf')

def build_graph(edges):
    graph = {}
    for edge in edges:
        i, j = edge
        graph[i] = graph.get(i, []) + [j, float('inf')]
    return graph

