def longest_increasing_subsequence(arr):
    if not arr:
        return 0

    n = len(arr)
    dp = [[0] * n for _ in range(n)]

    for i in range(1, n):
        dp[i][i] = 1

    for i in range(2, n):
        for j in range(0, i):
            if arr[i] > arr[j]:
                dp[i][j] = dp[i][j-1] + 1
            else:
                dp[i][j] = max(dp[i][j-1], dp[i-1][j])

    max_length = 0
    for i in range(n):
        max_length = max(max_length, dp[i][n-1])

    return max_length

