def binary_search(arr, x):
    """
    The binary search function that wraps the actual search function p2.
    """
    return p2(arr, 0, len(arr) - 1, x)

def p2(arr, start, end, x):
    """
    The actual binary search function that takes two arguments, start and end,
    which represent the index range of the array to be searched.
    """
    if start > end:
        return -1

    mid = (start + end) // 2

    if arr[mid] == x:
        return mid

    if arr[mid] < x:
        return p2(arr, start, mid - 1, x)

    return p2(arr, mid + 1, end, x)

