def lis(arr):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 1

    for i in range(1, n):
        for j in range(i, n):
            if arr[i] > arr[j]:
                dp[i][j] = dp[i][j - 1] + 1
            else:
                dp[i][j] = max(dp[i][j], dp[i - 1][j])

    max_length = 0
    max_start = 0

    for i in range(n):
        for j in range(n):
            if dp[i][j] > max_length:
                max_length = dp[i][j]
                max_start = i

    return max_length, max_start

