Here's a Python program that implements the described algorithm for finding the shortest path between a given start node and a destination node in a weighted graph using a Fibonacci heap data structure:
```python
import heapq

def fibonacci_heap_insert_or_update(heap, node, distance):
    if node not in heap:
        heapq.heappush(heap, (distance, node))
    else:
        heapq.heappush(heap, (distance, node))
        if distance < heap[0][0]:
            heapq.heapify(heap)

def shortest_path_length(graph, start_node, destination_node):
    visited_nodes = set()
    unknown_nodes = [(0, start_node)]
    distance_map = {start_node: 0}

    while unknown_nodes:
        min_distance, node = heapq.heappop(unknown_nodes)

        if node == destination_node:
            return min_distance

        if node in visited_nodes:
            continue

        visited_nodes.add(node)

        for successor_node, weight in graph[node].items():
            if successor_node not in distance_map:
                distance_map[successor_node] = min_distance + weight
                fibonacci_heap_insert_or_update(unknown_nodes, successor_node, distance_map[successor_node])

    return float('inf')

# Example usage:
graph = {
    'A': {'B': 1, 'C': 2},
    'B': {'A': 1, 'D': 3},
    'C': {'A': 2, 'D': 4},
    'D': {'B': 3, 'E': 5}
}

start_node = 'A'
destination_node = 'E'

shortest_path = shortest_path_length(graph, start_node, destination_node)
print(f"Shortest path length from {start_node} to {destination_node}: {shortest_path}")
```
This program defines a `fibonacci_heap_insert_or_update` function to maintain the Fibonacci heap, a `shortest_path_length` function to find the shortest path between the start node and the destination node, and a `distance_map` to store the distances from the start node to all other nodes in the graph. The program uses the Fibonacci heap to keep track of the nodes and their corresponding distances, and iterates over the successors of the current node to find the minimum distance to the destination node.

