import heapq
from collections import defaultdict

def fibonacci_heap_insert_or_update(heap, node, distance):
    if node not in heap:
        heapq.heappush(heap, (node, distance))
    else:
        if distance > heap[node][1]:
            heapq.heappop(heap)
            heapq.heappush(heap, (node, distance))

def fibonacci_heap_get(heap, node):
    return heap[node][1] if node in heap else float('inf')

def shortest_path_length(line_length, start, destination):
    graph = defaultdict(float)
    for (u, v), weight in line_length.items():
        graph[u] = graph.get(u, 0) + weight

    start_distance = 0
    destination_distance = float('inf')
    fibonacci_heap = {}

    def dfs(node):
        if node == destination:
            return
        for (u, v), weight in line_length.items():
            if u == node:
                new_distance = graph[u] + weight
                if new_distance < destination_distance:
                    destination_distance = new_distance
                    fibonacci_heap_insert_or_update(fibonacci_heap, v, new_distance + start_distance)
            else:
                new_distance = graph[u] + weight + graph[v]
                if new_distance < destination_distance:
                    destination_distance = new_distance
                    fibonacci_heap_insert_or_update(fibonacci_heap, u, new_distance + start_distance)
        for (u, v), weight in line_length.items():
            if v == node:
                new_distance = graph[u] + weight + start_distance
                fibonacci_heap_insert_or_update(fibonacci_heap, u, new_distance)

    fibonacci_heap_insert_or_update(fibonacci_heap, start, start_distance)
    dfs(start)

    return destination_distance if destination_distance < float('inf') else float('inf')

# Example usage:
line_length = {('A', 'B'): 1, ('B', 'C'): 2, ('C', 'D'): 3, ('A', 'D'): 6}
start = 'A'
destination = 'D'

shortest_path_length(line_length, start, destination)
```
This program defines the required functions and implements the depth-first search algorithm with a Fibonacci heap to keep track of the shortest distances from the start node to all visited nodes. The `shortest_path_length` function returns the shortest path length between the specified start node and destination node, or `float('inf')` if no path is found.

