```python
from typing import Type, Union

class UserInput:
    pass

class Region:
    def __init__(self, condition: Union[str, Type[UserInput]], action: Union[str, Type[UserInput]]):
        self.condition = condition
        self.action = action

    def __call__(self, value: Union[str, UserInput]):
        if isinstance(value, str):
            return self.condition(value)
        elif isinstance(value, UserInput):
            return self.action(value)

def main():
    user_input = UserInput()
    while True:
        region = Region(str, str)
        if region(user_input):
            break
        user_input = input("Enter a value (or press enter to quit): ")
    print(f"Exiting program based on user input: {user_input}")

if __name__ == "__main__":
    main()
