def fibonacci(n):
    # If the input is 0 or 1, return the input number
    if n <= 1:
        return n

    # If the input is greater than the sum of the first two Fibonacci numbers,
    # return the sum of the first two Fibonacci numbers
    elif n > sum(fibonacci(0), fibonacci(1)):
