from fastapi import FastAPI

def http_decorator(func):
    def wrapper(*args, **kwargs):
        response = func(*args, **kwargs)
        return {"message": "Request successful", "data": response}
    return wrapper

app = FastAPI()

@http_decorator
def add(a: int, b: int) -> int:
    return a + b

