```python
import heapq

class GridNode:
    def __init__(self, x, y, cost=0):
        self.x = x
        self.y = y
        self.cost = cost
        self.successors = {}

    def add_successor(self, successor):
        self.successors[successor] = self.cost + successor.cost

class FibonacciHeap:
    def __init__(self):
        self.heap = []

    def insert(self, node):
        heapq.heappush(self.heap, (node.cost, node))

    def extract_min(self):
        return heapq.heappop(self.heap)[1]

    def update_successor(self, node, successor):
        cost = node.cost + successor.cost
        self.insert(successor)
        node.successors[successor] = cost

def shortest_path(grid, start, end):
    start_node = GridNode(start.x, start.y, 0)
    end_node = GridNode(end.x, end.y, 0)
    fibonacci_heap = FibonacciHeap()
    fibonacci_heap.insert(start_node)

    current = start_node
    while current != end_node:
        min_node = fibonacci_heap.extract_min()
        successors = min_node.successors

        for successor in successors.values():
            if successor == end_node:
                return min_node, successors[successor]

            if successor not in fibonacci_heap:
                fibonacci_heap.insert(successor)
                min_node.successors[successor] = min_node.cost + successor.cost

        current = min_node

    return None, None

def main():
    grid = [
        (0, 1, 2),
        (3, 4, 5),
        (6, 7, 8),
    ]

    start = (0, 0)
    end = (2, 2)

    path, length = shortest_path(grid, start, end)

    if path:
        print("Shortest path:", path)
    else:
        print("No path found")

if __name__ == "__main__":
    main()
```
