def p1(arr, x):
    if not arr:
        return -1

    mid = len(arr) // 2
    return p2(arr, x, 0, mid)

def p2(arr, x, start, end):
    if start == end:
        return -1 if arr[start] != x else start

    mid = (start + end) // 2

    if arr[mid] == x:
        return mid

    if arr[mid] < x:
        return p2(arr, x, start, mid - 1)

    return p2(arr, x, mid + 1, end)

