```python
class Time:
    def __init__(self, hours, minutes, seconds):
        self.hours = hours
        self.minutes = minutes
        self.seconds = seconds

    def __str__(self):
        return f"{self.hours}:{self.minutes}:{self.seconds}"

    def __add__(self, other):
        if isinstance(other, Time):
            return Time(self.hours + other.hours, self.minutes + other.minutes, self.seconds + other.seconds)
        else:
            return Time(self.hours + other, self.minutes + other, self.seconds + other)

    def __iadd__(self, other):
        if isinstance(other, Time):
            self.hours += other.hours
            self.minutes += other.minutes
            self.seconds += other.seconds
        else:
            self.hours += other
            self.minutes += other
            self.seconds += other

    def __sub__(self, other):
        if isinstance(other, Time):
            return Time(self.hours - other.hours, self.minutes - other.minutes, self.seconds - other.seconds)
        else:
            return Time(self.hours - other, self.minutes - other, self.seconds - other)

    def __isub__(self, other):
        if isinstance(other, Time):
            self.hours -= other.hours
            self.minutes -= other.minutes
            self.seconds -= other.seconds
        else:
            self.hours -= other
            self.minutes -= other
            self.seconds -= other

    def __repr__(self):
        return f"Time({self.hours}, {self.minutes}, {self.seconds})"
```
