            if weight_by_line.get((i, j)) is not None:
                if divide_by_point(weight_by_line, i) & divide_by_point(weight_by_line, j):
                    mst_edges.add((i, j))
                    divide_by_point(weight_by_line, i, j)
                    divide_by_point(weight_by_line, j, i)
    return mst_edges

def divide_by_point(weight_by_line, i):
    visited = set()
    stack = [(i, visited)]
    while stack:
        u, v = stack.pop()
        visited.add(u)
        for j in range(len(weight_by_line)):
            if j not in visited and weight_by_line.get((u, j)) is not None:
                if j not in v:
                    stack.append((j, v))
    return visited

