    for distance, item in heap:
        if item == node:
            return distance
    return float('inf')

def insert_or_update(heap, node, distance):
    for distance_, item in heap:
        if item == node:
            if distance < distance_:
                heappush(heap, (distance, node))
            return
    heappush(heap, (distance, node))

def shortest_path_length(graph, start, target):
    visited = defaultdict(int)
    visited[start] = 0
    heap = [(0, start)]

    while True:
        distance, node = heappop(heap)

        if node == target:
            return visited[target]

        for successor in graph[node]:
            if not visited[successor]:
                new_distance = distance + graph[node][successor]
                if successor not in visited:
                    visited[successor] = new_distance
                    insert_or_update(heap, successor, new_distance)

    return float('inf')

def graph_from_edges(edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    return graph

