```python
import heapq
from collections import defaultdict

class WeightedGraph:
    def __init__(self):
        self.adj_matrix = {}

    def add_edge(self, u, v, weight):
        if u not in self.adj_matrix:
            self.adj_matrix[u] = defaultdict(float)
        self.adj_matrix[u][v] = weight
        if v not in self.adj_matrix:
            self.adj_matrix[v] = defaultdict(float)
        self.adj_matrix[v][u] = weight

    def shortest_path_length(self, start, end):
        queue = [(start, [start])]
        visited = set()

        while queue:
            (current, path) = heapq.heappop(queue)

            if current in visited:
                continue

            visited.add(current)

            if current == end:
                return len(path)

            for neighbor, weight in self.adj_matrix[current].items():
                new_neighbor = (neighbor, path + [neighbor])
                heapq.heappush(queue, new_neighbor)

        return float('inf')

def main():
    graph = WeightedGraph()

    # Add edges to the graph
    graph.add_edge(0, 1, 1)
    graph.add_edge(1, 2, 2)
    graph.add_edge(2, 3, 3)
    graph.add_edge(3, 4, 4)
    graph.add_edge(4, 5, 5)
    graph.add_edge(5, 0, 6)

    start = 0
    end = 4

    print(graph.shortest_path_length(start, end))  # Output: 6

if __name__ == "__main__":
    main()
```
